const ctx = $('Input').first().json;
const library = $('Read Strategy Library').all().map(i => i.json);
const clientStatus = $('Read Client Strategy Status').all().map(i => i.json).filter(r => r.client_id);
return [{ json: { ...ctx, _library: library, _client_status: clientStatus } }];

const ctx = $('Input').first().json;
const userContent = 'Client: ' + ctx.client_name +
'\n\n--- STRATEGY LIBRARY (Firm-Approved rows) ---\n' + JSON.stringify($json._library ?? []) +
'\n\n--- CLIENT DATA (financials + tax position + profile + questionnaire) ---\n' +
JSON.stringify({ profile: { entity_type: ctx.entity_type, state: ctx.state_primary, has_c_corp: ctx.has_c_corp, has_pte_election: ctx.has_pte_election },
  financials: ctx.financials ?? null, tax_position: ctx.tax_position ?? null,
  payroll: ctx.payroll ?? null, questionnaire: ctx.questionnaire ?? null, email_digest: ctx.email_digest ?? null }) +
'\n\n--- ALREADY IMPLEMENTED / REJECTED FOR THIS CLIENT ---\n' + JSON.stringify($json._client_status ?? []);
const payload = {
  model: 'claude-opus-4-8',
  max_tokens: 16000,
  thinking: { type: 'adaptive' },
  system: "You are screening a curated tax-strategy library against one client's current data to surface planning opportunities for a CPA to evaluate. You are given: (1) the Strategy Library (each row: name, category, trigger conditions, savings heuristic, authority, risk rating, review status); (2) the client's data (financials, tax position, profile, questionnaire answers); (3) the client's strategy status (already implemented or previously rejected).\nRules:\n- ONLY consider strategies whose review_status is \"Firm-Approved\". Ignore Draft rows.\n- SKIP any strategy already implemented or previously rejected for this client.\n- A strategy is a candidate ONLY if the client's data actually satisfies its trigger conditions. Do not force matches.\n- Estimate annual savings using the row's heuristic and the client's real numbers. Show your inputs. If you can't compute a number, give a range and mark it \"rough\".\n- Rank candidates by estimated savings.\n- This is a screen, not advice. Every candidate must be validated by the professional (and, for Moderate/Aggressive risk, a Blue J-backed memo) before it reaches the client. Never present a strategy as recommended.\nOutput only the JSON schema.",
  messages: [{ role: 'user', content: userContent }],
  output_config: { effort: 'high', format: { type: 'json_schema', schema: {"type": "object", "additionalProperties": false, "required": ["candidates", "skipped"], "properties": {"candidates": {"type": "array", "items": {"type": "object", "additionalProperties": false, "required": ["strategy_id", "strategy_name", "risk_rating", "why_it_triggers", "estimated_annual_savings", "savings_basis", "requires_memo", "confidence"], "properties": {"strategy_id": {"type": "string"}, "strategy_name": {"type": "string"}, "risk_rating": {"type": "string", "enum": ["Conservative", "Moderate", "Aggressive"]}, "why_it_triggers": {"type": "string"}, "estimated_annual_savings": {"type": ["number", "null"]}, "savings_basis": {"type": "string"}, "requires_memo": {"type": "boolean"}, "confidence": {"type": "string", "enum": ["high", "medium", "rough"]}}}}, "skipped": {"type": "array", "items": {"type": "object", "additionalProperties": false, "required": ["strategy_name", "reason"], "properties": {"strategy_name": {"type": "string"}, "reason": {"type": "string", "enum": ["already_implemented", "previously_rejected", "triggers_not_met", "draft_row"]}}}}}} } }
};
return [{ json: { ...$json, payload } }];

// Structured outputs: the JSON arrives as a string in content[0].text.
const text = $json.content?.[0]?.text ?? '{}';
let out; try { out = JSON.parse(text); } catch (e) { out = { parse_error: true, raw: text }; }
const ctx = $('Input').first().json;
return [{ json: { ...ctx, strategies: out } }];
